require 'json';require 'digest'
o=File.expand_path(__dir__);parse=->(p){rows=File.read(p).scan(/^test (\S+) \.\.\. (ok|ignored[^\n]*)$/);raise 'duplicate tests' unless rows.size==rows.map(&:first).uniq.size;rows.to_h}
prior=File.expand_path('../dictionary-batch-candidate-2026-10-30/library-tests.log',o);expected=parse.call(prior)
{
 'interpreter::nested_publication::collection_dictionary_storage_tests::'=>%w[mixed_dictionary_storage_preserves_snapshots_and_moves_into_unique_leaf dictionary_storage_bounds_distinct_keys_and_rewrites_full_tables],
 'interpreter::nested_publication::collection_dictionary_promotion_tests::'=>%w[dictionary_promotion_preserves_inline_many_and_collection_history same_key_dictionary_changes_keep_compact_storage promotion_reservation_tracks_known_keys_not_logical_limit first_collection_insertion_preserves_missing_keys_snapshots_and_owned_publication initial_collection_insertion_requires_policy_unique_owners_and_budget initial_text_and_bytes_reuse_keys_and_preserve_snapshots],
 'interpreter::nested_dictionary_collection_proof::tests::'=>%w[accepts_stable_deep_owners_and_mixed_payloads_without_changing_policy_layout counted_loops_bound_work_but_do_not_preallocate_that_bound observations_callbacks_aliases_and_replacements_keep_fallback keys_parameters_and_counter_mutation_are_checked],
 'interpreter::capture_independence::'=>%w[nested_struct_payload_keeps_operator_capture_and_bounded_admission]
}.each{|prefix,names|names.each{|n|raise 'existing' if expected.key?(prefix+n);expected[prefix+n]='ok'}}
actual=parse.call(o+'/library-tests.log');raise "membership #{(expected.keys-actual.keys).inspect} / #{(actual.keys-expected.keys).inspect}" unless actual==expected
raise 'summary' unless File.read(o+'/library-tests.log').include?('1301 passed; 0 failed; 8 ignored; 0 measured; 0 filtered out;')
JSON.parse(File.read(o+'/source-manifest.json')).each{|p,h|raise 'source drift' unless Digest::SHA256.file(p).hexdigest==h}
File.write(o+'/library-verified.json',JSON.pretty_generate({status:'passed',passed:1301,ignored:8,prior_log_sha256:Digest::SHA256.file(prior).hexdigest,log_sha256:Digest::SHA256.file(o+'/library-tests.log').hexdigest})+"\n");puts '1301 exact library passes/8ignored verified'

